def transform(grid):
    R,C=len(grid),len(grid[0]);
    for t in range(R):
      for b in range(R-1,t+1,-1):
       for l in range(C):
        for r in range(C-1,l+1,-1):
         if all(grid[t][j]==2 and grid[b][j]==2 for j in range(l,r+1)) and all(grid[i][l]==2 and grid[i][r]==2 for i in range(t,b+1)):
          return [row[l+1:r] for row in grid[t+1:b]]
    return grid

def transform(grid):
    R,C=len(grid),len(grid[0]);
    for t in range(R):
      for b in range(t+2,R):
       for l in range(C):
        for r in range(l+2,C):
         if all(grid[t][j]==2 and grid[b][j]==2 for j in range(l,r+1)) and all(grid[i][l]==2 and grid[i][r]==2 for i in range(t,b+1)): return [x[l+1:r] for x in grid[t+1:b]]
    return []
